def generate_subsets(nums: list[int]) -> list[list[int]]:
    res = []
    def backtrack(start, path):
        res.append(path[:])
        for i in range(start, len(nums)):
            path.append(nums[i])
            backtrack(i + 1, path)
            path.pop()
    nums.sort()
    backtrack(0, [])
    return sorted([sorted(sub) for sub in res])
